Post Date: 2012-10-01T13:52:44Z
Current Date: April 4 2025
Title: Concerned about Model security?
Description: Hi,

I have a simple Backbone Model/View combo that is validating a login field and then calling `.save` so the data is sent to the server to process. 

The problem I've just realised is that when inspecting the Model after calling `.save` I can see the password is being stored in the Model as plain text so all a developer has to do is dynamically change the JavaScript via the standard built-in browser developer tools to see the user's password.

How can I implement a username/password login securely with Backbone?

My current Model/View code is as follows...
## Model:

``` js
define(['Backbone'], function(){

    return Backbone.Model.extend({
        url: '/login/',

        validate: function (attributes) {
            var errors = [];

            if (attributes.account.indexOf('@') === -1) {
                errors.push({
                    field: 'account',
                    value: attributes.account
                });
            }

            if (attributes.password === '') {
                errors.push({
                    field: 'password',
                    value: attributes.password
                });
            }

            if (errors.length) {
                return errors
            }
        }
    });

});
```
## View:

``` js
define(['../Models/CustomerLogin', 'Backbone'], function (CustomerLogin) {

    return Backbone.View.extend({
        initialize: function(){
            // Store the form element and hide it
            this.form = this.$el.find('form');

            // Store the Model object for easy reference
            this.model = new CustomerLogin();

            // Store reference to error message box
            this.error_message = $('#js-loginerror')
        },

        // The containing element
        el: $('#js-customerlogin'),

        // Selectors are scoped to the parent element
        events: {
            'click #js-loginbtn': 'toggle_display',
            'submit form': 'store_user_details'
        },

        toggle_display: function(){
            this.form.slideToggle();
        },

        store_user_details: function (e) {
            // I stored this hash in a variable as it looked cleaner passing it to `save` method below
            var fields = {
                account: this.form[0].elements[0].value,
                password: this.form[0].elements[1].value
            };

            // Scope of `this` is lost within the error callback below
            var self = this;

            // When we call `save` it automatically validates all data
            // So if there are any errors with what we're trying to save then it'll fail
            this.model.save(fields, {
                error: function(){
                    self.error_message.addClass('is-error');
                },
                success: function(data){
                    self.error_message.removeClass('is-error');
                    alert('LOG USER IN - WARNING!!! Backbone.Model has plain text storage of password!!!');
                    console.log(self.model.attributes, 'ALL DEVELOPER HAS TO DO IS CHANGE JS DYNAMICALLY AND HE HAS PASSWORD!');
                }
            });

            e.preventDefault();
        }
    });

});
```


